bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
const e=process.env,pid='sp_76f23430d1c29ca355960a95';
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,
password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:6000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try{
 const q=await db.query("SELECT p.seller_user_id,p.price_stars,t.chat_id,t.message_thread_id,t.telegram_message_id,t.status FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[pid]);
 if(q.rowCount!==1||Number(q.rows[0].price_stars)!==50||Number(q.rows[0].chat_id)!==-1002373696859||Number(q.rows[0].message_thread_id)!==4640)
 throw Error('STK_BUYER_VIEW_TARGET_INVALID');
 const m=q.rows[0],token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const api=createTelegramBotApi({token,fetchImpl:outgoing.fetch,timeoutMs:18000});
 const chat=await api('getChat',{chat_id:-1002373696859});
 const seller=await api('getChatMember',{chat_id:-1002373696859,user_id:Number(m.seller_user_id)});
 const bot=await api('getMe',{});
 if(bot?.is_bot!==true||String(bot.username).toLowerCase()!=='createvdobot')throw Error('STK_BOT_IDENTITY_INVALID');
 console.log('STK_PAID_MEDIA_POST_ID='+Number(m.telegram_message_id));
 console.log('STK_TOPIC_POST_STATE='+String(m.status));
 console.log('STK_SELLER_GROUP_ROLE='+String(seller?.status||'UNKNOWN'));
 console.log('STK_IS_FORUM='+String(chat.is_forum===true));
 const x=await db.query("SELECT COUNT(*)::int AS n FROM videobot_sticker_paid_photo_sales WHERE product_id=$1",[pid]);
 console.log('STK_VERIFIED_STARS_PURCHASE_COUNT='+x.rows[0].n);
 console.log('STK_READ_ONLY_BUYER_DIAG=PASS');
}finally{await outgoing.close();await db.end()}
NODE
